import dev.touchxbox.pad.*;
import java.util.*;
public final class MotionReportTest {
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static int u16(byte[] b,int p){return (b[p]&255)|((b[p+1]&255)<<8);}
    static int f16(byte[] b,int p){return u16(b,p);}
    static int x(byte[] b,int p){return (b[p]&255)|((b[p+1]&15)<<8);}
    static int y(byte[] b,int p){return ((b[p+1]&255)>>4)|((b[p+2]&255)<<4);}
    public static void main(String[] args)throws Exception{
        short[] imu=MotionCodec.convert(new float[]{0,0,9.80665f},new float[]{0,0,0},0);check(Arrays.equals(imu,new short[]{0,0,4096,0,0,0}),"1 g in NS native counts");
        short[] rotated=MotionCodec.convert(new float[]{9.80665f,0,0},new float[]{0,0,(float)Math.PI/2},1);check(rotated[0]==4096&&rotated[1]==0&&rotated[5]==1282,"Landscape axes and radian conversion");
        short[] cap=MotionCodec.convert(new float[]{Float.NaN,100000,Float.POSITIVE_INFINITY},new float[3],0);check(cap[0]==32767&&cap[1]==0&&cap[2]==0,"Saturate and reject non-finite samples");
        PadState s=new PadState();byte[] b=SwitchProCodec.report(s.report(),new short[][]{imu,imu,imu},25);check(b.length==49&&b[0]==0x30&&b[1]==5&&x(b,6)==2048&&y(b,6)==2048&&u16(b,17)==4096,"NS full packet layout");
        s.stick(false,1,-1);s.stick(true,-1,1);s.faceButtons((1<<PadState.A)|(1<<PadState.Y));s.button(PadState.LB,true);s.button(PadState.GUIDE,true);s.trigger(true,1);s.hat(8);b=SwitchProCodec.report(s.report(),null,0);check(x(b,6)==4095&&y(b,6)==4095&&x(b,9)==0&&y(b,9)==0,"NS stick packing and Y polarity");check((b[3]&255)==134&&(b[4]&255)==32&&(b[5]&255)==74,"NS logical buttons, digital trigger, diagonal");
        byte[] output=new byte[16];output[0]=1;output[10]=0x10;output[11]=0x20;output[12]=0x60;output[15]=24;byte[] reply=SwitchProCodec.reply(output,b);check(reply.length==64&&(reply[13]&255)==0x90&&u16(reply,26)==16384&&u16(reply,38)==13371&&reply[3]==b[3],"SPI calibration and preserved buttons");output[15]=45;check(SwitchProCodec.reply(output,b)[13]==0,"Bound SPI reads");check((SwitchProCodec.reply(new byte[]{(byte)0x80,2},b)[0]&255)==0x81,"USB handshake reply");
        byte[] ds=Ds4Codec.report(new PadState().report(),imu,16000000);check(ds.length==64&&ds[0]==1&&ds[1]==(byte)128&&ds[5]==8&&u16(ds,21)==8192&&(ds[35]&128)!=0&&(ds[39]&128)!=0,"DS4 axes, gravity, no phantom touches");byte[] cal=Ds4Codec.feature(2);check(cal.length==37&&u16(cal,7)==16000&&(short)u16(cal,9)==-16000&&u16(cal,23)==8192,"DS4 calibration denominators");
        byte[] fpv=FpvCodec.report(s.report());check(fpv.length==18&&f16(fpv,0)==0&&f16(fpv,2)==0&&f16(fpv,4)==65535&&f16(fpv,6)==65535&&f16(fpv,10)==65535,"FPV Mode 2 channel assignment");
        PadState chord=new PadState();chord.button(PadState.LB,true);chord.nextFrame(0);chord.faceButtons(1<<PadState.Y);chord.nextFrame(0);chord.faceButtons(1<<PadState.X);check(u16(chord.nextFrame(0),12)==((1<<PadState.X)|(1<<PadState.LB)),"Sector slide is atomic and preserves shoulder");
        PadState keys=new PadState();keys.keyboard("one",26,true);keys.keyboard("one",26,true);keys.keyboard("two",26,true);keys.keyboard("ctrl",224,true);byte[] frame=keys.nextFrame(0);check((frame[18]&4)!=0,"W down preserved");frame=keys.nextFrame(0);check((frame[43]&1)!=0,"Ctrl independent of W");keys.keyboard("one",26,false);frame=keys.nextFrame(0);check((frame[18]&4)!=0,"Duplicate mapped key holds until last owner releases");keys.keyboard("two",26,false);frame=keys.nextFrame(0);check((frame[18]&4)==0&&(frame[43]&1)!=0,"W release preserves Ctrl");keys.reset();check(Arrays.equals(Arrays.copyOfRange(keys.nextFrame(0),15,47),new byte[32]),"Reset releases every keyboard key");
        PadState radio=new PadState(ControllerProtocol.FPV);check(f16(FpvCodec.report(radio.report()),4)==0,"First FPV packet has zero throttle");radio.stick(false,.7f,-.5f);check(f16(FpvCodec.report(radio.report()),4)==49151,"Retained vertical value is the actual CH3 wire value");radio.reset();check(f16(FpvCodec.report(radio.nextFrame(0)),4)==0,"Reset releases throttle to minimum");for(int a=0;a<3;a++)for(int z=0;z<3;z++){radio.auxiliary(6,a);radio.auxiliary(7,z);byte[] channels=FpvCodec.report(radio.report());check(f16(channels,12)==(a==0?0:a==1?32768:65535)&&f16(channels,14)==(z==0?0:z==1?32768:65535),"Independent CH7 and CH8 three-position switches");}radio.auxiliary(4,2);radio.auxiliary(5,1);check(f16(FpvCodec.report(radio.report()),8)==65535&&Math.abs(f16(FpvCodec.report(radio.report()),10)-32768)<=1,"CH5 and CH6 separate auxiliary channels");radio.reset();check(f16(FpvCodec.report(radio.report()),12)==32768&&f16(FpvCodec.report(radio.report()),14)==32768,"Auxiliary channels reset to middle");radio.configure(ControllerProtocol.XBOX);check(u16(radio.report(),2)==32768,"Switching out of FPV restores centered gamepad axes");
        System.out.println("PASS: NS/DS4/FPV wire packets, zero-throttle startup/reset, IMU scaling/rotation, calibration handshakes, atomic sector transitions, keyboard chords and releases");
    }
}
